$projDir = "D:\inforsys\notificationservices"\nif (-not (Test-Path $projDir)) { New-Item -ItemType Directory -Path $projDir | Out-Null }\nSet-Location $projDir\n\n# create project\ndotnet new webapi -n NotificationService -o . --no-https\n\n# add packages\ndotnet add package Dapper --version 2.1.0\ndotnet add package Microsoft.Data.SqlClient --version 5.2.1\ndotnet add package Scriban --version 4.1.0\n\n# overwrite csproj to ensure net8\n$csproj = @'\n<Project Sdk="Microsoft.NET.Sdk.Web">\n\n  <PropertyGroup>\n    <TargetFramework>net8.0</TargetFramework>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>enable</Nullable>\n  </PropertyGroup>\n\n  <ItemGroup>\n    <PackageReference Include="Dapper" Version="2.1.0" />\n    <PackageReference Include="Microsoft.Data.SqlClient" Version="5.2.1" />\n    <PackageReference Include="Scriban" Version="4.1.0" />\n  </ItemGroup>\n\n</Project>\n'@\nSet-Content -Path "NotificationService.csproj" -Value $csproj -Encoding UTF8\n\n# appsettings\n$app = @'\n{\n  "ConnectionStrings": {\n    "Default": "Server=.;Database=notificationdb;Trusted_Connection=True;TrustServerCertificate=True;"\n  },\n  "Logging": {\n    "LogLevel": {\n      "Default": "Information",\n      "Microsoft.Hosting.Lifetime": "Information"\n    }\n  }\n}\n'@\nSet-Content -Path "appsettings.json" -Value $app -Encoding UTF8\n\n# create folders\n$folders = @(\n  "Domain\Entities",\n  "Application\Interfaces",\n  "Application\Handlers",\n  "Infrastructure\Data",\n  "Infrastructure\Providers",\n  "Infrastructure\Template",\n  "Infrastructure\RateLimiting",\n  "Infrastructure\CircuitBreaker",\n  "Api\Controllers",\n  "Worker",\n  "docs"\n)\nforeach ($f in $folders) { if (-not (Test-Path $f)) { New-Item -ItemType Directory -Path $f | Out-Null } }\n\n# SQL init\n$init = @'\n-- Create database and table script (run in MSSQL)\nCREATE TABLE message_log (\n    id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,\n    tenant_id VARCHAR(50) NOT NULL,\n    channel VARCHAR(20) NOT NULL,\n    recipient VARCHAR(255) NOT NULL,\n    template_code VARCHAR(100) NOT NULL,\n    data_json NVARCHAR(MAX) NULL,\n    status VARCHAR(20) NOT NULL,\n    retry_count INT NOT NULL DEFAULT 0,\n    error_message NVARCHAR(MAX) NULL,\n    next_retry_at DATETIME NULL,\n    processing_at DATETIME NULL,\n    created_at DATETIME NOT NULL,\n    sent_at DATETIME NULL\n);\n\nCREATE INDEX IX_message_log_status_created_at ON message_log(status, created_at);\n'@\nSet-Content -Path "docs\init_db.sql" -Value $init -Encoding UTF8\n\n# Domain/Entities/MessageLog.cs\n$msg = @'\nusing System;\n\nnamespace Domain.Entities\n{\n    public class MessageLog\n    {\n        public Guid Id { get; set; }\n        public string TenantId { get; set; } = "";\n        public string Channel { get; set; } = "";\n        public string Recipient { get; set; } = "";\n        public string TemplateCode { get; set; } = "";\n        public string? DataJson { get; set; }\n        public string Status { get; set; } = "";\n        public int RetryCount { get; set; }\n        public string? ErrorMessage { get; set; }\n        public DateTime? NextRetryAt { get; set; }\n        public DateTime? ProcessingAt { get; set; }\n        public DateTime CreatedAt { get; set; }\n        public DateTime? SentAt { get; set; }\n    }\n}\n'@\nSet-Content -Path "Domain\Entities\MessageLog.cs" -Value $msg -Encoding UTF8\n\n# Application/Interfaces/IMessageRepository.cs\n$repo = @'\nusing Domain.Entities;\nusing System;\nusing System.Collections.Generic;\nusing System.Threading.Tasks;\n\nnamespace Application.Interfaces\n{\n    public interface IMessageRepository\n    {\n        Task InsertAsync(MessageLog message);\n        Task<MessageLog?> GetByIdAsync(Guid id);\n        Task<IEnumerable<MessageLog>> ClaimPendingMessagesAsync(int batchSize);\n        Task UpdateOnSuccessAsync(Guid id, DateTime sentAt);\n        Task UpdateOnFailureAsync(Guid id, int retryCount, string error, DateTime? nextRetryAt, string status);\n        Task RescheduleAsync(Guid id, DateTime nextRetryAt, string status, string? error = null);\n    }\n}\n'@\nSet-Content -Path "Application\Interfaces\IMessageRepository.cs" -Value $repo -Encoding UTF8\n\n# Infrastructure/Data/MessageRepository.cs\n$repoimpl = @'\nusing Application.Interfaces;\nusing Domain.Entities;\nusing Dapper;\nusing Microsoft.Data.SqlClient;\nusing Microsoft.Extensions.Configuration;\nusing System;\nusing System.Collections.Generic;\nusing System.Data;\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Data\n{\n    public class MessageRepository : IMessageRepository\n    {\n        private readonly string _conn;\n\n        public MessageRepository(Microsoft.Extensions.Configuration.IConfiguration config)\n        {\n            _conn = config.GetConnectionString("Default") ??\n                    throw new ArgumentNullException("Connection string 'Default' not found");\n        }\n\n        private IDbConnection CreateConnection() => new SqlConnection(_conn);\n\n        public async Task InsertAsync(MessageLog message)\n        {\n            const string sql = @"\nINSERT INTO message_log (id, tenant_id, channel, recipient, template_code, data_json, status, retry_count, created_at)\nVALUES (@Id, @TenantId, @Channel, @Recipient, @TemplateCode, @DataJson, @Status, @RetryCount, @CreatedAt)";\n            using var db = CreateConnection();\n            await db.ExecuteAsync(sql, message);\n        }\n\n        public async Task<MessageLog?> GetByIdAsync(Guid id)\n        {\n            const string sql = @"SELECT * FROM message_log WHERE id = @Id";\n            using var db = CreateConnection();\n            return await db.QueryFirstOrDefaultAsync<MessageLog>(sql, new { Id = id });\n        }\n\n        public async Task<IEnumerable<MessageLog>> ClaimPendingMessagesAsync(int batchSize)\n        {\n            var sql = @"\n;WITH cte AS (\n    SELECT TOP (@BatchSize) \n    FROM message_log\n    WHERE status = 'pending' AND (next_retry_at IS NULL OR next_retry_at <= GETDATE())\n    ORDER BY created_at\n)\nUPDATE cte\nSET status = 'processing', processing_at = GETDATE()\nOUTPUT inserted.\n";\n            using var db = CreateConnection();\n            return await db.QueryAsync<MessageLog>(sql, new { BatchSize = batchSize });\n        }\n\n        public async Task UpdateOnSuccessAsync(Guid id, DateTime sentAt)\n        {\n            const string sql = @"UPDATE message_log SET status = 'sent', sent_at = @SentAt WHERE id = @Id";\n            using var db = CreateConnection();\n            await db.ExecuteAsync(sql, new { Id = id, SentAt = sentAt });\n        }\n\n        public async Task UpdateOnFailureAsync(Guid id, int retryCount, string error, DateTime? nextRetryAt, string status)\n        {\n            const string sql = @"\nUPDATE message_log\nSET retry_count = @RetryCount,\n    error_message = @Error,\n    next_retry_at = @NextRetry,\n    status = @Status\nWHERE id = @Id";\n            using var db = CreateConnection();\n            await db.ExecuteAsync(sql, new { Id = id, RetryCount = retryCount, Error = error, NextRetry = nextRetryAt, Status = status });\n        }\n\n        public async Task RescheduleAsync(Guid id, DateTime nextRetryAt, string status, string? error = null)\n        {\n            const string sql = @"UPDATE message_log SET next_retry_at = @NextRetryAt, status = @Status, error_message = @Error WHERE id = @Id";\n            using var db = CreateConnection();\n            await db.ExecuteAsync(sql, new { Id = id, NextRetryAt = nextRetryAt, Status = status, Error = error });\n        }\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Data\MessageRepository.cs" -Value $repoimpl -Encoding UTF8\n\n# Api/Controllers/MessagesController.cs\n$controller = @'\nusing Application.Interfaces;\nusing Domain.Entities;\nusing Microsoft.AspNetCore.Mvc;\nusing Microsoft.Extensions.Logging;\nusing System;\nusing System.Threading.Tasks;\n\nnamespace Api.Controllers\n{\n    [ApiController]\n    [Route("api/messages")]\n    public class MessagesController : ControllerBase\n    {\n        private readonly IMessageRepository _repo;\n        private readonly ILogger<MessagesController> _logger;\n\n        public MessagesController(IMessageRepository repo, ILogger<MessagesController> logger)\n        {\n            _repo = repo;\n            _logger = logger;\n        }\n\n        public class CreateRequest\n        {\n            public string TenantId { get; set; } = "";\n            public string Channel { get; set; } = "";\n            public string To { get; set; } = "";\n            public string TemplateCode { get; set; } = "";\n            public object? Data { get; set; }\n        }\n\n        [HttpPost]\n        public async Task<IActionResult> Post([FromBody] CreateRequest req)\n        {\n            var id = Guid.NewGuid();\n            var message = new MessageLog\n            {\n                Id = id,\n                TenantId = req.TenantId,\n                Channel = req.Channel,\n                Recipient = req.To,\n                TemplateCode = req.TemplateCode,\n                DataJson = req.Data == null ? null : System.Text.Json.JsonSerializer.Serialize(req.Data),\n                Status = "pending",\n                RetryCount = 0,\n                CreatedAt = DateTime.UtcNow\n            };\n\n            await _repo.InsertAsync(message);\n            _logger.LogInformation("Inserted message {MessageId} tenant:{Tenant} channel:{Channel}", id, req.TenantId, req.Channel);\n            return Ok(new { message_id = id });\n        }\n\n        [HttpGet("{id:guid}")]\n        public async Task<IActionResult> Get(Guid id)\n        {\n            var msg = await _repo.GetByIdAsync(id);\n            if (msg == null) return NotFound();\n            return Ok(new\n            {\n                status = msg.Status,\n                retry_count = msg.RetryCount,\n                sent_at = msg.SentAt\n            });\n        }\n    }\n}\n'@\nSet-Content -Path "Api\Controllers\MessagesController.cs" -Value $controller -Encoding UTF8\n\n# Worker/MessageProcessingService.cs\n$worker = @'\nusing Application.Handlers;\nusing Application.Interfaces;\nusing Domain.Entities;\nusing Infrastructure.CircuitBreaker;\nusing Infrastructure.RateLimiting;\nusing Microsoft.Extensions.Hosting;\nusing Microsoft.Extensions.Logging;\nusing System;\nusing System.Collections.Generic;\nusing System.Linq;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace Worker\n{\n    public class MessageProcessingService : BackgroundService\n    {\n        private readonly IMessageRepository _repo;\n        private readonly IEnumerable<IMessageHandler> _handlers;\n        private readonly ILogger<MessageProcessingService> _logger;\n        private readonly IRateLimiter _rateLimiter;\n        private readonly ICircuitBreaker _circuitBreaker;\n\n        private readonly SemaphoreSlim _concurrency;\n\n        public MessageProcessingService(\n            IMessageRepository repo,\n            IEnumerable<IMessageHandler> handlers,\n            IRateLimiter rateLimiter,\n            ICircuitBreaker circuitBreaker,\n            ILogger<MessageProcessingService> logger)\n        {\n            _repo = repo;\n            _handlers = handlers;\n            _logger = logger;\n            _rateLimiter = rateLimiter;\n            _circuitBreaker = circuitBreaker;\n            _concurrency = new SemaphoreSlim(5); // max concurrency 5\n        }\n\n        protected override async Task ExecuteAsync(CancellationToken stoppingToken)\n        {\n            _logger.LogInformation("MessageProcessingService started");\n            while (!stoppingToken.IsCancellationRequested)\n            {\n                try\n                {\n                    var batch = (await _repo.ClaimPendingMessagesAsync(20)).ToList();\n                    if (batch.Count == 0)\n                    {\n                        await Task.Delay(TimeSpan.FromSeconds(2), stoppingToken);\n                        continue;\n                    }\n\n                    var tasks = new List<Task>();\n                    foreach (var msg in batch)\n                    {\n                        await _concurrency.WaitAsync(stoppingToken);\n                        tasks.Add(ProcessMessageAsync(msg).ContinueWith(t => _concurrency.Release()));\n                    }\n\n                    await Task.WhenAll(tasks);\n                }\n                catch (OperationCanceledException) { break; }\n                catch (Exception ex)\n                {\n                    _logger.LogError(ex, "Error in worker loop");\n                    await Task.Delay(TimeSpan.FromSeconds(2), stoppingToken);\n                }\n\n                await Task.Delay(TimeSpan.FromSeconds(2), stoppingToken);\n            }\n            _logger.LogInformation("MessageProcessingService stopping");\n        }\n\n        private async Task ProcessMessageAsync(MessageLog msg)\n        {\n            var handler = _handlers.FirstOrDefault(h => string.Equals(h.Channel, msg.Channel, StringComparison.OrdinalIgnoreCase));\n            if (handler == null)\n            {\n                _logger.LogWarning("No handler for channel {Channel}", msg.Channel);\n                await _repo.UpdateOnFailureAsync(msg.Id, msg.RetryCount + 1, "No handler", null, "failed");\n                return;\n            }\n\n            // Circuit breaker check (global per channel)\n            if (_circuitBreaker.IsOpen(msg.Channel))\n            {\n                _logger.LogWarning("Circuit open for channel {Channel}. Rescheduling message {Id}", msg.Channel, msg.Id);\n                // small reschedule\n                var next = DateTime.UtcNow.AddSeconds(5);\n                await _repo.RescheduleAsync(msg.Id, next, "pending", "circuit_open");\n                return;\n            }\n\n            // Rate limiter per tenant + channel\n            if (!_rateLimiter.TryConsume(msg.TenantId, msg.Channel))\n            {\n                _logger.LogInformation("Rate limit exceeded for tenant {Tenant} channel {Channel}. Rescheduling {Id}", msg.TenantId, msg.Channel, msg.Id);\n                var next = DateTime.UtcNow.AddSeconds(5);\n                await _repo.RescheduleAsync(msg.Id, next, "pending", "rate_limited");\n                return;\n            }\n\n            try\n            {\n                await handler.HandleAsync(msg);\n                await _repo.UpdateOnSuccessAsync(msg.Id, DateTime.UtcNow);\n                _circuitBreaker.OnSuccess(msg.Channel);\n                _logger.LogInformation("Message {Id} sent (channel {Channel})", msg.Id, msg.Channel);\n            }\n            catch (Exception ex)\n            {\n                _logger.LogError(ex, "Failed to send message {Id}", msg.Id);\n                var retry = msg.RetryCount + 1;\n                _circuitBreaker.OnFailure(msg.Channel);\n                if (retry > 5)\n                {\n                    await _repo.UpdateOnFailureAsync(msg.Id, retry, ex.Message, null, "failed");\n                    _logger.LogWarning("Message {Id} marked failed after {Retry}", msg.Id, retry);\n                }\n                else\n                {\n                    // exponential backoff: delay = 2^retry * 5s + jitter(0-5)\n                    var delaySeconds = Math.Pow(2, retry) * 5;\n                    var jitter = (new Random()).NextDouble() * 5;\n                    var next = DateTime.UtcNow.AddSeconds(delaySeconds + jitter);\n                    await _repo.UpdateOnFailureAsync(msg.Id, retry, ex.Message, next, "pending");\n                    _logger.LogInformation("Message {Id} scheduled retry {Retry} at {Next}", msg.Id, retry, next);\n                }\n            }\n        }\n    }\n}\n'@\nSet-Content -Path "Worker\MessageProcessingService.cs" -Value $worker -Encoding UTF8\n\n# Application/Handlers/IMessageHandler.cs\n$ih = @'\nusing Domain.Entities;\nusing System.Threading.Tasks;\n\nnamespace Application.Handlers\n{\n    public interface IMessageHandler\n    {\n        string Channel { get; }\n        Task HandleAsync(MessageLog message);\n    }\n}\n'@\nSet-Content -Path "Application\Handlers\IMessageHandler.cs" -Value $ih -Encoding UTF8\n\n# Application/Handlers/EmailHandler.cs\n$email = @'\nusing Domain.Entities;\nusing Infrastructure.Providers;\nusing Infrastructure.Template;\nusing Microsoft.Extensions.Logging;\nusing System.Threading.Tasks;\n\nnamespace Application.Handlers\n{\n    public class EmailHandler : IMessageHandler\n    {\n        public string Channel => "email";\n\n        private readonly ITemplateRenderer _renderer;\n        private readonly IEmailProvider _provider;\n        private readonly ILogger<EmailHandler> _logger;\n\n        public EmailHandler(ITemplateRenderer renderer, IEmailProvider provider, ILogger<EmailHandler> logger)\n        {\n            _renderer = renderer;\n            _provider = provider;\n            _logger = logger;\n        }\n\n        public async Task HandleAsync(MessageLog message)\n        {\n            var template = $"Hello {{name}}, this is template {message.TemplateCode} for email.";\n            var body = await _renderer.RenderAsync(template, message.DataJson);\n            await _provider.SendAsync(message.TenantId, message.Recipient, $"Template {message.TemplateCode}", body);\n            _logger.LogInformation("EmailHandler processed message {Id}", message.Id);\n        }\n    }\n}\n'@\nSet-Content -Path "Application\Handlers\EmailHandler.cs" -Value $email -Encoding UTF8\n\n# Application/Handlers/WhatsAppHandler.cs\n$wa = @'\nusing Domain.Entities;\nusing Infrastructure.Providers;\nusing Infrastructure.Template;\nusing Microsoft.Extensions.Logging;\nusing System.Threading.Tasks;\n\nnamespace Application.Handlers\n{\n    public class WhatsAppHandler : IMessageHandler\n    {\n        public string Channel => "whatsapp";\n\n        private readonly ITemplateRenderer _renderer;\n        private readonly IWhatsAppProvider _provider;\n        private readonly ILogger<WhatsAppHandler> _logger;\n\n        public WhatsAppHandler(ITemplateRenderer renderer, IWhatsAppProvider provider, ILogger<WhatsAppHandler> logger)\n        {\n            _renderer = renderer;\n            _provider = provider;\n            _logger = logger;\n        }\n\n        public async Task HandleAsync(MessageLog message)\n        {\n            var template = $"WA template {message.TemplateCode}: Hi {{name}}!";\n            var body = await _renderer.RenderAsync(template, message.DataJson);\n            await _provider.SendAsync(message.TenantId, message.Recipient, body);\n            _logger.LogInformation("WhatsAppHandler processed message {Id}", message.Id);\n        }\n    }\n}\n'@\nSet-Content -Path "Application\Handlers\WhatsAppHandler.cs" -Value $wa -Encoding UTF8\n\n# Infrastructure/Providers/IEmailProvider.cs\n$iep = @'\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Providers\n{\n    public interface IEmailProvider\n    {\n        Task SendAsync(string tenantId, string to, string subject, string body);\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Providers\IEmailProvider.cs" -Value $iep -Encoding UTF8\n\n# Infrastructure/Providers/EmailProvider.cs\n$eimpl = @'\nusing Microsoft.Extensions.Logging;\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Providers\n{\n    public class EmailProvider : IEmailProvider\n    {\n        private readonly ILogger<EmailProvider> _logger;\n\n        public EmailProvider(ILogger<EmailProvider> logger)\n        {\n            _logger = logger;\n        }\n\n        public Task SendAsync(string tenantId, string to, string subject, string body)\n        {\n            _logger.LogInformation("EmailProvider: tenant={Tenant} to={To} subject={Subject} body={Body}", tenantId, to, subject, body);\n            return Task.CompletedTask;\n        }\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Providers\EmailProvider.cs" -Value $eimpl -Encoding UTF8\n\n# Infrastructure/Providers/IWhatsAppProvider.cs\n$iwa = @'\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Providers\n{\n    public interface IWhatsAppProvider\n    {\n        Task SendAsync(string tenantId, string to, string message);\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Providers\IWhatsAppProvider.cs" -Value $iwa -Encoding UTF8\n\n# Infrastructure/Providers/WhatsAppProvider.cs\n$waimpl = @'\nusing Microsoft.Extensions.Logging;\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Providers\n{\n    public class WhatsAppProvider : IWhatsAppProvider\n    {\n        private readonly ILogger<WhatsAppProvider> _logger;\n\n        public WhatsAppProvider(ILogger<WhatsAppProvider> logger)\n        {\n            _logger = logger;\n        }\n\n        public Task SendAsync(string tenantId, string to, string message)\n        {\n            _logger.LogInformation("WhatsAppProvider: tenant={Tenant} to={To} message={Message}", tenantId, to, message);\n            return Task.CompletedTask;\n        }\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Providers\WhatsAppProvider.cs" -Value $waimpl -Encoding UTF8\n\n# Infrastructure/Template/ITemplateRenderer.cs\n$tr = @'\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Template\n{\n    public interface ITemplateRenderer\n    {\n        Task<string> RenderAsync(string template, string? dataJson);\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Template\ITemplateRenderer.cs" -Value $tr -Encoding UTF8\n\n# Infrastructure/Template/ScribanTemplateRenderer.cs\n$sr = @'\nusing Scriban;\nusing System.Text.Json;\nusing System.Threading.Tasks;\n\nnamespace Infrastructure.Template\n{\n    public class ScribanTemplateRenderer : ITemplateRenderer\n    {\n        public Task<string> RenderAsync(string template, string? dataJson)\n        {\n            var model = string.IsNullOrWhiteSpace(dataJson) ? new { } : JsonSerializer.Deserialize<object>(dataJson)!;\n            var tpl = Template.Parse(template);\n            var result = tpl.Render(model, member => member.Name);\n            return Task.FromResult(result);\n        }\n    }\n}\n'@\nSet-Content -Path "Infrastructure\Template\ScribanTemplateRenderer.cs" -Value $sr -Encoding UTF8\n\n# Infrastructure/RateLimiting/IRateLimiter.cs\n$rl = @'\nnamespace Infrastructure.RateLimiting\n{\n    public interface IRateLimiter\n    {\n        bool TryConsume(string tenantId, string channel);\n    }\n}\n'@\nSet-Content -Path "Infrastructure\RateLimiting\IRateLimiter.cs" -Value $rl -Encoding UTF8\n\n# Infrastructure/RateLimiting/InMemoryRateLimiter.cs\n$rlimpl = @'\nusing System;\nusing System.Collections.Concurrent;\n\nnamespace Infrastructure.RateLimiting\n{\n    public class InMemoryRateLimiter : IRateLimiter\n    {\n        private class Window\n        {\n            public long TimestampSec;\n            public int Count;\n        }\n\n        private readonly ConcurrentDictionary<string, Window> _map = new();\n        private readonly ConcurrentDictionary<string, int> _limits = new(StringComparer.OrdinalIgnoreCase)\n        {\n            ["email"] = 10,\n            ["whatsapp"] = 3\n        };\n\n        public bool TryConsume(string tenantId, string channel)\n        {\n            var key = $"{tenantId}:{channel}".ToLowerInvariant();\n            var nowSec = DateTimeOffset.UtcNow.ToUnixTimeSeconds();\n            var win = _map.GetOrAdd(key, _ => new Window { TimestampSec = nowSec, Count = 0 });\n\n            lock (win)\n            {\n                if (win.TimestampSec != nowSec)\n                {\n                    win.TimestampSec = nowSec;\n                    win.Count = 0;\n                }\n\n                var limit = _limits.TryGetValue(channel, out var l) ? l : 5;\n                if (win.Count >= limit) return false;\n                win.Count++;\n                return true;\n            }\n        }\n    }\n}\n'@\nSet-Content -Path "Infrastructure\RateLimiting\InMemoryRateLimiter.cs" -Value $rlimpl -Encoding UTF8\n\n# Infrastructure/CircuitBreaker/ICircuitBreaker.cs\n$cb = @'\nnamespace Infrastructure.CircuitBreaker\n{\n    public interface ICircuitBreaker\n    {\n        bool IsOpen(string channel);\n        void OnSuccess(string channel);\n        void OnFailure(string channel);\n    }\n}\n'@\nSet-Content -Path "Infrastructure\CircuitBreaker\ICircuitBreaker.cs" -Value $cb -Encoding UTF8\n\n# Infrastructure/CircuitBreaker/SimpleCircuitBreaker.cs\n$cbimpl = @'\nusing System;\nusing System.Collections.Concurrent;\n\nnamespace Infrastructure.CircuitBreaker\n{\n    public class SimpleCircuitBreaker : ICircuitBreaker\n    {\n        private class State\n        {\n            public int ConsecutiveFailures;\n            public DateTime? OpenUntil;\n            public bool HalfOpenAttempted;\n        }\n\n        private readonly ConcurrentDictionary<string, State> _states = new();\n\n        private readonly int _failureThreshold = 5;\n        private readonly TimeSpan _openDuration = TimeSpan.FromSeconds(60);\n\n        public bool IsOpen(string channel)\n        {\n            var state = _states.GetOrAdd(channel, _ => new State());\n            if (state.OpenUntil.HasValue)\n            {\n                if (DateTime.UtcNow < state.OpenUntil.Value) return true;\n                if (!state.HalfOpenAttempted)\n                {\n                    state.HalfOpenAttempted = true;\n                    return false; // allow one\n                }\n            }\n            return false;\n        }\n\n        public void OnSuccess(string channel)\n        {\n            var state = _states.GetOrAdd(channel, _ => new State());\n            state.ConsecutiveFailures = 0;\n            state.OpenUntil = null;\n            state.HalfOpenAttempted = false;\n        }\n\n        public void OnFailure(string channel)\n        {\n            var state = _states.GetOrAdd(channel, _ => new State());\n            state.ConsecutiveFailures++;\n            if (state.ConsecutiveFailures >= _failureThreshold)\n            {\n                state.OpenUntil = DateTime.UtcNow.Add(_openDuration);\n                state.HalfOpenAttempted = false;\n            }\n        }\n    }\n}\n'@\nSet-Content -Path "Infrastructure\CircuitBreaker\SimpleCircuitBreaker.cs" -Value $cbimpl -Encoding UTF8\n\n# Program.cs (replace)\n$program = @'\nusing Application.Handlers;\nusing Application.Interfaces;\nusing Infrastructure.CircuitBreaker;\nusing Infrastructure.Data;\nusing Infrastructure.Providers;\nusing Infrastructure.RateLimiting;\nusing Infrastructure.Template;\nusing Microsoft.AspNetCore.Builder;\nusing Microsoft.Extensions.DependencyInjection;\nusing Microsoft.Extensions.Hosting;\n\nvar builder = WebApplication.CreateBuilder(args);\n\nbuilder.Services.AddControllers();\nbuilder.Services.AddEndpointsApiExplorer();\nbuilder.Services.AddSwaggerGen();\n\n// register infrastructure\nbuilder.Services.AddSingleton<IMessageRepository, MessageRepository>();\nbuilder.Services.AddSingleton<ITemplateRenderer, ScribanTemplateRenderer>();\nbuilder.Services.AddSingleton<IEmailProvider, EmailProvider>();\nbuilder.Services.AddSingleton<IWhatsAppProvider, WhatsAppProvider>();\nbuilder.Services.AddSingleton<Infrastructure.RateLimiting.IRateLimiter, InMemoryRateLimiter>();\nbuilder.Services.AddSingleton<Infrastructure.CircuitBreaker.ICircuitBreaker, SimpleCircuitBreaker>();\n\n// handlers\nbuilder.Services.AddSingleton<IMessageHandler, EmailHandler>();\nbuilder.Services.AddSingleton<IMessageHandler, WhatsAppHandler>();\n\n// worker\nbuilder.Services.AddHostedService<Worker.MessageProcessingService>();\n\nvar app = builder.Build();\n\nif (app.Environment.IsDevelopment())\n{\n    app.UseSwagger();\n    app.UseSwaggerUI();\n}\n\napp.MapControllers();\n\napp.Run();\n'@\nSet-Content -Path "Program.cs" -Value $program -Encoding UTF8\n\nWrite-Host "Setup complete. Run 'dotnet restore' then update appsettings.json connection string and create DB/table using docs\init_db.sql.'"\n\n